L46_1.m_Crash = 30
L46_1.m_Talk_KOREA = "대정화 전쟁 속에서도 살아남은 로열 오페라 하우스의 라 트라비아타야!"
L46_1.m_fTalkTime = 0.03
L46_1.m_Talk_JPN = "大浄化戦争でも生き残ったロイヤルオペラハウスのラ・トラヴィアータなのよ？"
L46_1.m_Talk_ENG = "It's La Traviata! Performed at the Royal Opera House that survived the Grand Purification War!"
L46_1.m_Talk_TWN = "那可是在大淨化戰爭中倖存下來的皇家歌劇院演出的《茶花女》耶！"
L46_1.m_Talk_DEU = "It's La Traviata! Performed at the Royal Opera House that survived the Grand Purification War!"
L46_1.m_Talk_FRA = "It's La Traviata! Performed at the Royal Opera House that survived the Grand Purification War!"
L47_1 = {}
L47_1.m_CutScenKey_Talk = "OMEN_CHARADE_PROLOGUE1@30#Talk"
