L47_1.m_Pos = "R"
L47_1.m_Crash = 15
L47_1.m_Talk_KOREA = "틀림없이 일생일대의 공연이 될 거란 말이야! 표 구하느라 얼마나 고생했는데!"
L47_1.m_fTalkTime = 0.03
L47_1.m_Talk_JPN = "間違いなく一生に一度しか見られない公演になるわ！　チケット取るのにどれだけ苦労したかわかってるの？"
L47_1.m_Talk_ENG = "I'm telling you, this is guaranteed to be the performance of a lifetime! Do you know how hard it was to get these tickets?"
L47_1.m_Talk_TWN = "那絕對會是一生必看一次的演出啊！我可是費盡千辛萬苦才弄到票的耶！"
L47_1.m_Talk_DEU = "I'm telling you, this is guaranteed to be the performance of a lifetime! Do you know how hard it was to get these tickets?"
L47_1.m_Talk_FRA = "I'm telling you, this is guaranteed to be the performance of a lifetime! Do you know how hard it was to get these tickets?"
