L1_1.m_Talk_ENG = "If you want to watch it that badly, go alone. Why drag me into this?"
L1_1.m_Talk_TWN = "你想看的話自己來就好，幹嘛非要拉我下水？"
L1_1.m_Talk_DEU = "If you want to watch it that badly, go alone. Why drag me into this?"
L1_1.m_Talk_FRA = "If you want to watch it that badly, go alone. Why drag me into this?"
