L19_1 = "축사는 잘 들었습니다. 과연 샤레이드를 관리하는 시니어다운 훌륭한 연설이더군요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "祝辞、聞かせてもらいました。さすがはシャレードを管理するシニア。立派な演説でした。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I listened to your address. A fine speech, worthy of a Senior who governs Charade."
L18_1.m_Talk_ENG = L19_1
L19_1 = "我聽了你的致詞。果然是管理查雷德的Senior，演說很精彩。"
