L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "한편으로는 의외였답니다. 설마 이곳에서 시니어의 연설을 듣게 될 줄은 몰랐으니까요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "同時に意外でした。まさかここでシニアの演説を聞けるとは思わなかったので。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "In a way, it surprised me. I never imagined I'd hear your speech here of all places."
L19_1.m_Talk_ENG = L20_1
L20_1 = "不過我也很意外，沒想到會在這裡聽到你的致詞。"
