L38_1 = "맞아요, 제가 이 오페라를 처음 관람한 건 아주 어릴 적이었답니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "そうです。私が最初にこのオペラを観たのは、まだ本当に幼い時でした。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Yes. I first saw this opera when I was very young."
L37_1.m_Talk_ENG = L38_1
L38_1 = "對。我第一次觀賞這部歌劇時，年紀還很小。"
L37_1.m_Talk_TWN = L38_1
