L38_1.m_Pos = "R"
L39_1 = "제 조부님의 말씀에 따르면, 라 트라비아타의 초연은 그다지 성공적이지 못했다고 해요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "祖父の話によると、ラ・トラヴィアータの初演の反応はあまりよくなかったそうです。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "According to my grandfather, its premiere was not particularly successful."
L38_1.m_Talk_ENG = L39_1
L39_1 = "據我祖父所說，這部作品首演時其實並不成功。"
