L31_1 = "SWAN_SIX_NULL_QM"
L30_1.m_CharStrID = L31_1
L31_1 = "이 세계에서 있었던 1999년의 보수 공사 때문에 극장의 모습은 달라진 모양이지만."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
