L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "R"
L39_1 = "대정화 전쟁에서 당신이 이끌던 국제 연합군이 이곳을 지켜내지 못했다면."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "大浄化戦争であなたが率いた国際連合軍がここを守りきれていなかったら……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "If the Multinational Coalition Forces you once led had failed to protect this place during the Grand Purification War..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "若非你在大淨化戰爭中率領的國際聯軍守住了這裡，"
L38_1.m_Talk_TWN = L39_1
L39_1 = "If the Multinational Coalition Forces you once led had failed to protect this place during the Grand Purification War..."
