L40_1 = "SWAN_SIX_NULL_QM"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L40_1 = "이 극장 또한, 여느 멸망한 세계들처럼 역사의 뒤안길로 사라져 버리고 말았겠죠."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "この劇場も、これまで滅び去った幾多の世界のように、歴史の裏へと消えてしまっていたでしょう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "This theater, like so many ruined worlds, would have vanished into the shadows of history."
L39_1.m_Talk_ENG = L40_1
L40_1 = "這座劇院恐怕也會像其他滅亡的世界被歷史掩埋。"
