L41_1 = "아까부터 영문을 알 수 없는 소리를 지껄이는군."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "先程から訳のわからないことを。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "You've been rambling nonsense for a while now."
L40_1.m_Talk_ENG = L41_1
L41_1 = "從剛才開始，你就一直說些莫名其妙的話。"
