L42_1 = "하고 싶은 말이 뭐지? 날 해칠 생각이 없다면, 이방인이 내게 무슨 볼일인가?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "何が言いたい？　危害を加えるつもりがないなら、異邦人が私に何の用がある？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "What is it you want? If you don't intend to harm me, what business does an outsider have with me?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "你到底想說什麼？若不是來害我，找我有什麼目的？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "What is it you want? If you don't intend to harm me, what business does an outsider have with me?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "What is it you want? If you don't intend to harm me, what business does an outsider have with me?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
