L43_1 = "SWAN_SIX_NULL_QM"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "R"
L43_1 = "이해해요. 원래부터 이 세계 주민인 당신 입장에는 다소 혼란스러울 수도 있겠군요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "わかります。元からこの世界の住人であるあなたからすれば、多少混乱してもおかしくありません。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I understand. From your perspective, as someone native to this world, it must all seem confusing."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我理解，對原本就生活在這個世界的你來說，確實難以消化。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "I understand. From your perspective, as someone native to this world, it must all seem confusing."
L42_1.m_Talk_DEU = L43_1
L43_1 = "I understand. From your perspective, as someone native to this world, it must all seem confusing."
