L46_1 = "당신과 거래를 하고 싶어요, 리하르트 베르너."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "リヒャルト・ベルナー、あなたと取引がしたいのです。"
