L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "그렇습니다. 제가 당신에게 바라는 것은 공신력 있고 확실한 신분……."
L47_1.m_Talk_KOREA = L48_1
