L44_1 = "멤버들의 행적이 외부로 드러나지 않도록 하라는 건가요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "メンバーの動きが外にバレないようにする、ということでしょうか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "You want me to keep the members' whereabouts from being revealed to the outside?"
