L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "각본을 꾸미는 당신의 재능에 가장 어울리는 역할이라고 판단했어요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "脚本を作りあげる君の才能に最も相応しい役割だと判断しました。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I believe it's the perfect role that matches your talents for devising scripts."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我們認為這個職責非常適合你的劇本寫作才華。"
