L49_1 = 0.3
L47_1[L48_1] = L49_1
L48_1 = "타인의 발자국을 지운다는 건 제가 그 발자국의 가장 가까운 곳에 있어야 한다는 뜻이죠."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "他人の足跡を消すということは、私がその足跡と一番近い場所に居なければならないということですね。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Being able to erase another's footprints means that I have to be the closest to those footprints."
L47_1.m_Talk_ENG = L48_1
L48_1 = "要消除別人的腳印就表示我必須離他們非常近。"
