L49_1 = "m_bCharPinup"
L48_1[L49_1] = true
L49_1 = "<color=#ffd34c>외부인</color>인 저에게 그런 일을 맡기고 함부로 신뢰하는 건 비밀결사의 리더가 보일 법한 행동은 아니네요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "<color=#ffd34c>部外者</color>である私にそのような仕事を任せ、むやみに信頼するとは、秘密組織のリーダーが取るべき行動とは思えませんね。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And entrusting an <color=#ffd34c>outsider</color> to do that doesn't seem like something a leader of a secret organization should do."
L48_1.m_Talk_ENG = L49_1
L49_1 = "把這樣的任務託付給我這個<color=#ffd34c>外人</color>，似乎不像是一個秘密組織的首領會有的行為。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "And entrusting an <color=#ffd34c>outsider</color> to do that doesn't seem like something a leader of a secret organization should do."
L48_1.m_Talk_DEU = L49_1
L49_1 = "And entrusting an <color=#ffd34c>outsider</color> to do that doesn't seem like something a leader of a secret organization should do."
L48_1.m_Talk_FRA = L49_1
