L51_1 = 0.3
L49_1[L50_1] = L51_1
L50_1 = "그렇기 때문에 이 세계의 많은 정보가 필요한 당신에겐 저의 제안을 거절할 이유가 없겠죠."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "だからこそ、この世界の情報を多く必要とする君は、僕の提案を断る理由がないはずです。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "You have no reason to decline this offer since you need all the information you can get about this world."
L49_1.m_Talk_ENG = L50_1
L50_1 = "所以，對於需要盡可能多收集這個世界的情報的你來說，沒有理由拒絕我的提議。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "You have no reason to decline this offer since you need all the information you can get about this world."
L49_1.m_Talk_DEU = L50_1
