L50_1[L51_1] = true
L51_1 = "당신에게도 이곳에서 이루고 싶은 궁극의 목적이 있을 테니까요. 우리 육익은 개인의 목적을 존중하는 편이거든요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "君にとってもここで成し遂げたい究極の目的があるはずですから。僕たち六翼は個人の目的を尊重していますよ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I'm sure you have something you wish to achieve here. And Six Wings respects everyone's individual goals."
L50_1.m_Talk_ENG = L51_1
L51_1 = "在這裡，你可能也有自己想要實現的終極目標，而我們六翼非常尊重成員的個人目的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "I'm sure you have something you wish to achieve here. And Six Wings respects everyone's individual goals."
