L25_1 = "SWAN_SIX_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "어쩌면 우리가 가는 길은 결국에는 돌고 돌아, 같은 목적지를 향하게 될지도 모릅니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "もしかすると、私たちの進む道は……巡り巡って、同じ終着点に繋がるかもしれません。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Then perhaps, after many twists and turns, the path we walk may ultimately lead us to the same destination."
L24_1.m_Talk_ENG = L25_1
L25_1 = "或許我們兜兜轉轉，最後仍會走向同一個終點。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "Then perhaps, after many twists and turns, the path we walk may ultimately lead us to the same destination."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Then perhaps, after many twists and turns, the path we walk may ultimately lead us to the same destination."
L24_1.m_Talk_FRA = L25_1
