L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "물론, 그 각본이 완성되기 위해서는 기적과 기적이 겹쳐야 가능하겠지만……."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "もちろん、その脚本が完成するためには、奇跡に奇跡を重ねる必要がありますが……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Of course, for that script to be completed, it would require miracles piled upon miracles..."
L25_1.m_Talk_ENG = L26_1
L26_1 = "當然，若要完成那份劇本，勢必要奇蹟疊加奇蹟才有可能……"
