L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "그리고 지금까지 제가 구상했던 수많은 각본들 또한 종국에 실패로 돌아가고 말았죠."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "そして今まで私が練り上げた数多くの脚本も、最後は失敗してしまった。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "And the countless scripts I devised until now all ended in failure as well."
L28_1.m_Talk_ENG = L29_1
L29_1 = "而我至今構想的無數劇本，也全都迎來了失敗的結局。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "And the countless scripts I devised until now all ended in failure as well."
L28_1.m_Talk_DEU = L29_1
L29_1 = "And the countless scripts I devised until now all ended in failure as well."
L28_1.m_Talk_FRA = L29_1
