L34_1.m_CharScale = L35_1
L34_1.m_CharScaleTime = 0.01
L35_1 = "당신이 말한 대로, 세계를 온전히 지켜내는 것과 그것을 부숴서라도 지켜내는 것은 전혀 다르니까요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "あなたが言ったとおり、世界を完全な形で守ることと、それを壊してでも守り通すことはまったく違いますからね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "As you said, preserving the world intact and preserving it even if one must break it are entirely different things."
L34_1.m_Talk_ENG = L35_1
L35_1 = "正如你所說，「完整地守護世界」與「即使將其摧毀也要守護它」，兩者截然不同。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "As you said, preserving the world intact and preserving it even if one must break it are entirely different things."
